*{{cite book|last=Hardacre|first=Helen|title=Shinto. A History|chapter=Medieval Shinto and the Arts|publisher=Oxford University Press|pages=177–206|year=2017|doi=10.1093/acprof:oso/9780190621711.003.0007|isbn=9780190621742}}
*{{cite book|last=Kim|first=Sujung|title=Shinra Myōjin and Buddhist Networks of the East Asian "Mediterranean"|publisher=University of Hawaii Press|year=2019|isbn=978-0-8248-8173-3|doi=10.1515/9780824881733|s2cid=243035601 }}
*{{cite journal|last=Pinnington|first=Noel J.|title=Invented Origins: Muromachi Interpretations of Okina Sarugaku|journal=Bulletin of the School of Oriental and African Studies, University of London| publisher=Cambridge University Press, School of Oriental and African Studies|volume=61|issue=3|year=1998|issn=1474-0699|jstor=3107756|pages=492–518|doi=10.1017/S0041977X00019315 |s2cid=162309137 |url=http://www.jstor.org/stable/3107756|access-date=2022-12-27}}
