{{short description|Buddhist deity from Japan}}
{{Infobox deity
| type = Japanese
| name = Matarajin
| image = Ushimatsuri.jpg
| caption = A depiction of the "ox festival" of Matarajin celebrated in {{ill|Kōryū-ji|en|Kōryū-ji|qid=Q3076920|lt=Kōryū-ji|1=Kōryū-ji}} in {{ill|Kyoto|en|Kyoto|qid=Q34600|lt=Kyoto|1=Kyoto}}.
| deity_of = God of obstacles, pestilence, performing arts and destiny
| script_name = Kanji
| script = 摩多羅神
| cult_center = {{ill|Mount Hiei|en|Mount Hiei|qid=Q748040|lt=Mount Hiei|1=Mount Hiei}}
